const tasks = $input.first().json.tasks || [];

function getCustomField(task, pattern) {
  return (task.custom_fields || []).find(f => (f.name || '').toLowerCase().includes(pattern));
}

function getRelatedClientId(task) {
  const cf = getCustomField(task, 'cliente_relacionado');
  const val = cf ? cf.value : null;
  if (Array.isArray(val) && val.length > 0) {
    return val[0].id || val[0].task_id || null;
  }
  return null;
}

const macroplans = tasks.map(t => ({
  clickup_task_id: t.id,
  client_clickup_id: getRelatedClientId(t),
  title: t.name,
  clickup_status: (t.status && t.status.status) || 'draft',
  description: t.text_content || t.description || null,
  period_start: null,
  period_end: null,
  creator_email: t.creator ? t.creator.email : null,
  responsible_email: (t.assignees && t.assignees[0]) ? t.assignees[0].email : null,
  attachments: [],
  deleted: false,
}));

return [{ json: { macroplans } }];

