// ATENÇÃO (ver Sticky Note "Lista de execução por projeto"): isto tenta ler
// a Lista de EXECUÇÃO do projeto (onde ficam as tarefas do dia a dia) de um
// custom field no card do Projeto. Ajuste o padrão do nome ('lista_execucao'
// / 'lista de tarefas') pro nome real, ou crie esse campo no ClickUp se
// ainda não existir - sem ele a branch D (tarefas de execução) não localiza
// as tarefas deste projeto.
function getExecutionListId(task) {
  const cf = getCustomField(task, 'lista_execucao') || getCustomField(task, 'lista de tarefas');
  return cf ? cf.value : null;
}

const projects = tasks.map(t => ({
  clickup_task_id: t.id,
  client_clickup_id: getRelatedId(t, 'cliente_relacionado'),
  macro_plan_clickup_id: getRelatedId(t, 'roadmap') || getRelatedId(t, 'planejamento'),
  clickup_list_id: getExecutionListId(t),
  title: t.name,
  objective: t.text_content || t.description || null,
  clickup_status: (t.status && t.status.status) || 'draft',
  attachments: [],
  deleted: false,
}));

return [{ json: { projects } }];

const tasks = $input.first().json.tasks || [];

function getCustomField(task, pattern) {
  return (task.custom_fields || []).find(f => (f.name || '').toLowerCase().includes(pattern));
}

function getFieldValue(task, pattern) {
  const cf = getCustomField(task, pattern);
  return cf ? cf.value : null;
}

function getRelatedClientId(task) {
  const val = getFieldValue(task, 'cliente_relacionado');
  if (Array.isArray(val) && val.length > 0) return val[0].id || val[0].task_id || null;
  return null;
}

function getDateField(task, pattern) {
  const val = getFieldValue(task, pattern);
  if (!val) return null;
  const ms = typeof val === 'string' ? parseInt(val, 10) : val;
  if (!ms) return null;
  return new Date(ms).toISOString().substring(0, 10);
}

const tasksPayload = tasks.map(t => ({
  clickup_task_id: t.id,
  project_id: null,
  list_id: t.list ? t.list.id : null,
  client_clickup_id: getRelatedClientId(t),
  title: t.name,
  description: t.text_content || t.description || null,
  clickup_status: (t.status && t.status.status) || 'backlog',
  clickup_priority: t.priority ? t.priority.priority : 'normal',
  task_type: 'administrativo',
  origin: 'ticket',
  destination: null,
  situation: (t.status && t.status.status) || null,
  due_date: getDateField(t, 'deadline'),
  approval_date: null,
  is_ticket: true,
  requester_name: getFieldValue(t, 'solicitante_nome'),
  requester_whatsapp: getFieldValue(t, 'solicitante_whatsapp'),
  requester_channel: null,
  creator_email: t.creator ? t.creator.email : null,
  executor_email: (t.assignees && t.assignees[0]) ? t.assignees[0].email : null,
  responsavel_email: null,
  attachments: [],
  deleted: false,
}));

return [{ json: { tasks: tasksPayload } }];

